// Fixed editorial ordering keeps IDs stable, disperses the multi-key items,
// and avoids repeatedly placing accepted options in the same position.
function orderedOptions(id){
  let seed=(2166136261^156)>>>0;
  for(const char of id)seed=Math.imul(seed^char.charCodeAt(0),16777619)>>>0;
  const order=[0,1,2,3];
  for(let i=3;i>0;i--){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;const j=(seed>>>0)%(i+1);[order[i],order[j]]=[order[j],order[i]];}
  return order;
}
const multiPositions={1:5,3:3,5:1,6:6,9:4,10:2};
export const practiceQuestions = weeks.flatMap(({week,items})=>{
  const arranged=[...items];
  if(multiPositions[week]!==undefined){const [multi]=arranged.splice(9,1);arranged.splice(multiPositions[week],0,multi);}
  return arranged.map((row,index)=>{
  const [lecture,section,text,options,correct,explanation]=row;
  const [title,file]=lectureSources[lecture];
  const id=`p${week}q${index+1}`,optionOrder=orderedOptions(id);
  return {bank:'additional',week,number:index+1,id,text,options:optionOrder.map(i=>options[i]),correct:optionOrder.map((original,i)=>correct.includes(original)?i:-1).filter(i=>i>=0),explanation,source:{lecture,title,file,section},type:correct.length>1?'multiple':'single'};
  });
});
